/* LLM Upgrade / Proof Section */
.llm-upgrade,
.llm-upgrade * {
  box-sizing: border-box;
  font-family: 'DM Sans', Arial, sans-serif;
}

.llm-upgrade {
  --bg: #07060D;
  --bg2: #0D0B18;
  --bg3: #141122;
  --silver: #F0EDF8;
  --body: #C8C5D8;
  --muted: #8A87A0;
  --dim: #5C596E;
  --line: rgba(255,255,255,.08);
  --ln2: rgba(255,255,255,.15);
  --green: #22C55E;
  color: var(--body);
  background: #000000;
}

.llm-upgrade img {
  display: block;
  max-width: 100%;
}

.llm-upgrade .w {
  max-width: 1360px;
  margin: 0 auto;
  padding: 0 24px;
}

.llm-upgrade .ws {
  max-width: 860px;
  margin: 0 auto;
  padding: 0 24px;
}

.llm-upgrade .sec {
  padding: 72px 0;
  border-bottom: 1px solid var(--line);
}

.llm-upgrade .sh {
  text-align: center;
  margin-bottom: 38px;
}

.llm-upgrade .ew {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .22em;
  text-transform: uppercase;
  margin-bottom: 14px;
}

.llm-upgrade .ewl {
  width: 18px;
  height: 1px;
  background: linear-gradient(90deg,#E8612A,#6247B0);
}

.llm-upgrade .gt,
.llm-upgrade .ewt {
  background: linear-gradient(135deg,#E8612A,#C43F7A,#6247B0,#C43F7A,#E8612A);
  background-size: 300% 300%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: llmGradientShift 5s ease infinite;
}

.llm-upgrade .sh h2 {
  font-size: clamp(30px,4vw,48px);
  line-height: 1.08;
  letter-spacing: -1.5px;
  color: var(--silver);
  margin: 0 0 10px;
}

.llm-upgrade .sh p {
  font-size: 15px;
  color: var(--muted);
  max-width: 780px;
  margin: 0 auto;
  line-height: 1.7;
}

@keyframes llmGradientShift {
  0%,100% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
}

/* LLM-Style Case Studies */
.llm-upgrade .csg {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 22px;
}

.llm-upgrade .csc {
  border-radius: 18px;
  border: 1px solid var(--line);
  background: var(--bg2);
  overflow: hidden;
  cursor: pointer;
  position: relative;
  transition: .3s;
}

.llm-upgrade .csc::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg,#E8612A,#C43F7A,#6247B0);
  z-index: 2;
}

.llm-upgrade .csc:hover {
  transform: translateY(-7px);
  border-color: var(--ln2);
  box-shadow: 0 28px 70px rgba(0,0,0,.5);
}

.llm-upgrade .csss {
  height: 190px;
  overflow: hidden;
  position: relative;
}

.llm-upgrade .csss::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 55px;
  background: linear-gradient(to top,var(--bg2),transparent);
}

.llm-upgrade .csss img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: top;
}

.llm-upgrade .csbody {
  padding: 22px 26px 24px;
}

.llm-upgrade .cslogo {
  height: 30px;
  margin-bottom: 13px;
}

.llm-upgrade .cslogo img {
  height: 100%;
