  border: 1px solid var(--line);
  border-radius: 8px;
}

.llm-upgrade .mm strong {
  display: block;
  font-size: 26px;
  font-weight: 700;
  line-height: 1;
  margin-bottom: 3px;
  background: linear-gradient(135deg,#E8612A,#C43F7A,#6247B0,#C43F7A,#E8612A);
  background-size: 300% 300%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: llmGradientShift 5s ease infinite;
}

.llm-upgrade .mm span {
  font-size: 9.5px;
  color: var(--muted);
  text-transform: uppercase;
}

.llm-upgrade .mlist {
  list-style: none;
  margin: 0;
  padding: 0;
}

.llm-upgrade .mlist li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 9px 0;
  border-bottom: 1px solid rgba(255,255,255,.04);
  font-size: 14px;
  color: var(--body);
}

.llm-upgrade .mlist li:last-child {
  border-bottom: none;
}

.llm-upgrade .mlc {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  flex-shrink: 0;
  margin-top: 2px;
  background: rgba(34,197,94,.1);
  border: 1px solid rgba(34,197,94,.2);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 9px;
  color: #22C55E;
}

.llm-upgrade .mdesc {
  font-size: 14px;
  color: var(--muted);
  line-height: 1.78;
  padding: 14px 16px;
  background: rgba(255,255,255,.03);
  border-radius: 8px;
  border-left: 2px solid rgba(196,63,122,.5);
}

@media(max-width:860px) {
  .llm-upgrade .csg {
    grid-template-columns: 1fr;
  }
}

